'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

function partitions(text, visit) {
  for (let first = 0; first <= text.length; first++) {
    for (let second = first; second <= text.length; second++) {
      visit([text.slice(0, first), '', text.slice(first, second), '', text.slice(second)]);
    }
  }
  visit(text.split(''));
}

test('grammar is invariant across chunk boundaries', () => {
  const fixtures = [
    ['', []], ['\uFEFF', []], ['\n', [['']]], ['\r\n\r\n\n\r', [[''], [''], [''], ['']]],
    ['a,', [['a', '']]], [',,', [['', '', '']]], ['""', [['']]],
    ['""""', [['"']]], ['a"b,c"d\r', [['a"b', 'c"d']]],
    ['\uFEFF"a,b","say ""hi"""\r\n"x\r\ny\rz\nw",tail,', [['a,b', 'say "hi"'], ['x\r\ny\rz\nw', 'tail', '']]],
    ['a\uFEFF,\uFEFFb\n\uFEFF', [['a\uFEFF', '\uFEFFb'], ['\uFEFF']]],
    ['😀,"😀"\r\n', [['😀', '😀']]],
  ];
  for (const [text, expected] of fixtures) {
    assert.deepEqual(parse(text), expected);
    partitions(text, chunks => {
      const parser = createParser({ header: true });
      const records = chunks.flatMap(chunk => parser.push(chunk));
      records.push(...parser.end());
      assert.deepEqual(records, expected, JSON.stringify(chunks));
    });
  }
});

test('push emits immediately and never repeats completed records', () => {
  const parser = createParser();
  assert.deepEqual(parser.push('a\r'), [['a']]);
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\n"b\r'), []);
  assert.deepEqual(parser.push('\n'), []);
  assert.deepEqual(parser.push('c"\r'), [['b\r\nc']]);
  assert.deepEqual(parser.push('\n\nlast,'), [['']]);
  assert.deepEqual(parser.end(), [['last', '']]);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push(''), Error);
  assert.throws(() => parser.push('later'), Error);
  const empty = createParser();
  assert.deepEqual(empty.end(), []);
  assert.deepEqual(empty.end(), []);
  assert.throws(() => empty.push(''), Error);
});

test('errors identify physical lines across all chunk boundaries', () => {
  const fixtures = [
    ['"a"x', 1, false], ['"a" ', 1, false], ['"a"\t', 1, false],
    ['a\r\n"b\r\nc\rd\ne"x', 5, false], ['"a\r\n" x', 2, false],
    ['"', 1, true], ['"a\r', 2, true], ['"a\r\n', 2, true],
    ['a\n"b\r\nc\rd\ne', 5, true], ['"a""', 1, true],
  ];
  for (const [text, line, atEnd] of fixtures) {
    partitions(text, chunks => {
      const parser = createParser();
      const check = error => error instanceof SyntaxError && error.message.includes(`line ${line}`);
      if (atEnd) {
        for (const chunk of chunks) parser.push(chunk);
        assert.throws(() => parser.end(), check);
      } else {
        assert.throws(() => { for (const chunk of chunks) parser.push(chunk); }, check);
      }
    });
  }
});

test('delimiter validation and custom UTF-16 delimiters', () => {
  for (const delimiter of ['', 'ab', '😀', '"', '\r', '\n', null, 1, false, {}, [';']]) {
    assert.throws(() => createParser({ delimiter }), RangeError);
    assert.throws(() => parse('', { delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  for (const delimiter of [';', '\t', ' ', '\0', '\uFEFF', '\uD83D']) {
    const text = `a${delimiter}"b${delimiter}c"${delimiter}\r\n`;
    partitions(text, chunks => {
      const parser = createParser({ delimiter });
      const records = chunks.flatMap(chunk => parser.push(chunk));
      records.push(...parser.end());
      assert.deepEqual(records, [['a', `b${delimiter}c`, '']]);
    });
  }
});

test('invalid chunks leave initial BOM handling intact and parsers independent', () => {
  const first = createParser();
  const second = createParser({ delimiter: ';' });
  for (const chunk of [undefined, null, 42, true, {}, [], Buffer.from('a'), new String('a')]) {
    assert.throws(() => first.push(chunk), TypeError);
  }
  assert.deepEqual(first.push(''), []);
  assert.deepEqual(first.push('\uFEFF"x'), []);
  assert.deepEqual(second.push('a;b\r'), [['a', 'b']]);
  assert.deepEqual(first.push('"\n'), [['x']]);
  assert.deepEqual(second.push('\nc;d'), []);
  assert.deepEqual(first.end(), []);
  assert.deepEqual(second.end(), [['c', 'd']]);
  assert.throws(() => parse(Buffer.from('a')), TypeError);
});

test('header conversion preserves duplicate names, padding and safe special keys', () => {
  const options = Object.freeze({ header: true });
  const objects = parse('x,x,x_2,x,__proto__,constructor,toString,\n1,2,3,4,5,6,7,8,ignored\nshort\n', options);
  const keys = ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString', ''];
  assert.deepEqual(Object.keys(objects[0]), keys);
  assert.deepEqual(Object.values(objects[0]), ['1', '2', '3', '4', '5', '6', '7', '8']);
  assert.deepEqual(Object.values(objects[1]), ['short', '', '', '', '', '', '', '']);
  for (const object of objects) {
    assert.equal(Object.getPrototypeOf(object), Object.prototype);
    for (const key of keys) {
      const descriptor = Object.getOwnPropertyDescriptor(object, key);
      assert.equal(descriptor.enumerable, true);
      assert.equal(descriptor.writable, true);
    }
  }
  assert.deepEqual(parse('', options), []);
  assert.deepEqual(parse('x\n', options), []);
  assert.deepEqual(parse('x\ny', { header: ['unused'] }), [['x'], ['y']]);
  const records = Object.freeze([Object.freeze(['a']), Object.freeze(['b', 'extra'])]);
  const header = Object.freeze(['__proto__', '__proto__']);
  const explicit = Object.freeze({ header });
  assert.deepEqual(toObjects(records, explicit), [
    { ['__proto__']: 'a', __proto___2: '' },
    { ['__proto__']: 'b', __proto___2: 'extra' },
  ]);
  assert.deepEqual(records, [['a'], ['b', 'extra']]);
  assert.deepEqual(header, ['__proto__', '__proto__']);
  assert.deepEqual(toObjects(records, { header: [] }), [{}, {}]);
});
